-- Series batches: complete Fist of the North Star (VIZ hardcover, vols 14-18)
-- and Fire Punch (VIZ paperback, vols 5-8) for staff review.
--
-- RAR has Fist of the North Star vols 1-13 of VIZ's 18-volume hardcover
-- (vol 18 published 23 Oct 2025) and Fire Punch vols 1-4 of 8. Each row
-- carries the exact ISBN-13 and two retailer pages showing that ISBN with
-- the volume title (web search, 25 Nov 2026). Nothing enters the catalogue
-- until a person approves it on Catalogue review ("Select a series"). Dates
-- and covers are left empty rather than guessed.
--
-- Additive only. To undo before review:
--   delete from catalogue_import_queue
--   where raw_payload ? 'series_batch' and status = 'pending_review'
--     and candidate_series in ('Fist of the North Star', 'Fire Punch');

begin;

insert into public.catalogue_import_queue
  (source_id, external_id, source_record_url, raw_payload, candidate_kind, candidate_title,
   candidate_series, candidate_volume_number, candidate_author, candidate_publisher,
   candidate_language, candidate_isbn_13, candidate_format)
select v.* from (values
